import{_ as a,o as t,c as r,a0 as o}from"./chunks/framework.DCluYYrN.js";const c=JSON.parse('{"title":"什麼是 KernelSU？","description":"","frontmatter":{},"headers":[],"relativePath":"zh_TW/guide/what-is-kernelsu.md","filePath":"zh_TW/guide/what-is-kernelsu.md"}'),l={name:"zh_TW/guide/what-is-kernelsu.md"};function s(n,e,i,h,u,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="what-is-kernelsu" tabindex="-1">什麼是 KernelSU？ <a class="header-anchor" href="#what-is-kernelsu" aria-label="Permalink to &quot;什麼是 KernelSU？ {#what-is-kernelsu}&quot;">​</a></h1><p>KernelSU 是 Android GKI 裝置的 Root 解決方案，它以核心模式運作，並直接在核心空間中為使用者空間應用程式授予 Root 權限。</p><h2 id="features" tabindex="-1">功能 <a class="header-anchor" href="#features" aria-label="Permalink to &quot;功能 {#features}&quot;">​</a></h2><p>KernelSU 的主要功能是它是<strong>基於核心的</strong>。 KernelSU 在核心空間中執行，所以它可以向我們提供從未有過的核心介面。例如，我們可以在核心模式中為任何處理程序新增硬體中斷點；我們可以在任何處理程序的實體記憶體中存取，而無人知曉；我們可以在核心空間攔截任何系統呼叫；等等。</p><p>此外，KernelSU 提供了 <a href="./metamodule.html">metamodule 系統</a>，這是一個用於模組管理的可插拔架構。與傳統 root 解決方案將掛載邏輯內建於核心的做法不同，KernelSU 將此工作委託給 metamodule。這允許您安裝 metamodule(如 <a href="https://github.com/tiann/KernelSU/tree/main/userspace/meta-overlayfs" target="_blank" rel="noreferrer">meta-overlayfs</a>)來提供對 <code>/system</code> 分區和其他分區的 systemless 修改。</p><h2 id="how-to-use" tabindex="-1">如何使用 <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;如何使用 {#how-to-use}&quot;">​</a></h2><p>請參閱：<a href="./installation.html">安裝</a></p><h2 id="how-to-build" tabindex="-1">如何建置 <a class="header-anchor" href="#how-to-build" aria-label="Permalink to &quot;如何建置 {#how-to-build}&quot;">​</a></h2><p>请參閱：<a href="./how-to-build.html">如何建置</a></p><h2 id="discussion" tabindex="-1">討論 <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;討論 {#discussion}&quot;">​</a></h2><ul><li>Telegram: <a href="https://t.me/KernelSU" target="_blank" rel="noreferrer">@KernelSU</a></li></ul>',11)])])}const _=a(l,[["render",s]]);export{c as __pageData,_ as default};
